1	// Pure reducer layer for the live-editing DOM to call into: takes a
2	// PendingState (see model.ts) and a user action's arguments, returns a NEW
3	// PendingState. No DOM, no mutation of the input state.
4	//
5	// Sits between the (future) DOM-wiring layer (double-click handlers, context
6	// menus, edit forms) and model.ts's pure validity/rendering functions. This
7	// module owns "how does a user action change the state", not "is the state
8	// valid" or "how does it render to CLI text" — those stay in model.ts.
9	//
10	// Design notes:
11	//
12	// - toggleComponent, for a BASE force: toggling a component OFF that
13	//   restores the update's `components` array to exactly the base force's
14	//   original `components` list PRUNES the update entry back out of
15	//   `updatedForces` entirely (rather than leaving a no-op
16	//   `{ components: [...same as base] }` entry sitting around). This keeps
17	//   state minimal and keeps `toCommandLines`'s diffing in model.ts from ever
18	//   emitting a synthetic no-op update line. If the pruned update object would
19	//   still have OTHER fields set (e.g. a prior description edit), the entry
20	//   is kept with components removed rather than deleted outright — only
21	//   `components` is pruned. Pinned by the "toggle a base force's component
22	//   back to its original state, with no other changes, removes the
23	//   updatedForces entry" test in actions.test.ts.
24	// - addForceRow generates tempIds as "NEW-<n>" where n is one more than the
25	//   count of existing addedForces entries whose tempId already matches the
26	//   "NEW-<number>" pattern (max + 1, not count + 1, so it can't collide after
27	//   an intervening removal — no removal action exists yet, but this is
28	//   future-proof at no cost). Returns { state, tempId } so the DOM layer can
29	//   open the freshly-created row in edit mode without having to search for
30	//   it.
31	// - updateForceField accumulates into the same updatedForces[id]/addedForces
32	//   entry across repeated calls, only ever touching the one field named.
33	
34	import type { AddedForce, PendingState, SnapshotAttractor, SnapshotComponent } from "./model";
35	
36	/** Returns true if two string arrays contain the same elements, ignoring order. */
37	function sameElements(a: readonly string[], b: readonly string[]): boolean {
38	  if (a.length !== b.length) return false;
39	  const sortedA = [...a].sort();
40	  const sortedB = [...b].sort();
41	  return sortedA.every((value, index) => value === sortedB[index]);
42	}
43	
44	/** Toggles `name` in/out of `components`, appending if absent, filtering out if present. */
45	function toggled(components: readonly string[], name: string): string[] {
46	  return components.includes(name) ? components.filter((c) => c !== name) : [...components, name];
47	}
48	
49	/** Toggles `componentName` in/out of the effective component list for the force identified by `forceKey` (a base force id or an added force's tempId). */
50	export function toggleComponent(state: PendingState, forceKey: string, componentName: string): PendingState {
51	  const addedIndex = state.addedForces.findIndex((f) => f.tempId === forceKey);
52	  if (addedIndex !== -1) {
53	    const target = state.addedForces[addedIndex]!;
54	    const nextForce: AddedForce = { ...target, components: toggled(target.components, componentName) };
55	    const nextAddedForces = [...state.addedForces];
56	    nextAddedForces[addedIndex] = nextForce;
57	    return { ...state, addedForces: nextAddedForces };
58	  }
59	
60	  const base = state.baseForces.find((f) => f.id === forceKey);
61	  if (base === undefined) {
62	    // Unknown force key — nothing to toggle against; return state unchanged.
63	    return state;
64	  }
65	
66	  const existingUpdate = state.updatedForces[forceKey];
67	  const effective = existingUpdate?.components ?? base.components;
68	  const nextComponents = toggled(effective, componentName);
69	
70	  const nextUpdatedForces = { ...state.updatedForces };
71	
72	  if (sameElements(nextComponents, base.components)) {
73	    if (existingUpdate === undefined) {
74	      // Nothing was set before, and toggling landed back on the base list —
75	      // no entry needed.
76	      return state;
77	    }
78	    const { components: _components, ...rest } = existingUpdate;
79	    if (Object.keys(rest).length === 0) {
80	      delete nextUpdatedForces[forceKey];
81	    } else {
82	      nextUpdatedForces[forceKey] = rest;
83	    }
84	  } else {
85	    nextUpdatedForces[forceKey] = { ...existingUpdate, components: nextComponents };
86	  }
87	
88	  return { ...state, updatedForces: nextUpdatedForces };
89	}
90	
91	/** Appends a new empty AddedForce of the given kind, returning the new state and the freshly generated unique tempId. */
92	export function addForceRow(
93	  state: PendingState,
94	  kind: "stressor" | "purpose",
95	): { state: PendingState; tempId: string } {
96	  let maxN = 0;
97	  for (const f of state.addedForces) {
98	    const match = /^NEW-(\d+)$/.exec(f.tempId);
99	    if (match) {
100	      const n = Number(match[1]);
101	      if (n > maxN) maxN = n;
102	    }
103	  }
104	  const tempId = `NEW-${maxN + 1}`;
105	
106	  const newForce: AddedForce = {
107	    tempId,
108	    kind,
109	    description: "",
110	    attractorId: "",
111	    naiveChangeOrFeature: "",
112	    outcomes: "",
113	    shortname: "",
114	    components: [],
115	  };
116	
117	  return { state: { ...state, addedForces: [...state.addedForces, newForce] }, tempId };
118	}
119	
120	/** Sets a single text field on the force identified by `forceKey` (base id or added-force tempId), preserving other already-set fields. */
121	export function updateForceField(
122	  state: PendingState,
123	  forceKey: string,
124	  field: "description" | "attractorId" | "naiveChangeOrFeature" | "outcomes" | "shortname",
125	  value: string,
126	): PendingState {
127	  const addedIndex = state.addedForces.findIndex((f) => f.tempId === forceKey);
128	  if (addedIndex !== -1) {
129	    const target = state.addedForces[addedIndex]!;
130	    const nextForce: AddedForce = { ...target, [field]: value };
131	    const nextAddedForces = [...state.addedForces];
132	    nextAddedForces[addedIndex] = nextForce;
133	    return { ...state, addedForces: nextAddedForces };
134	  }
135	
136	  const existingUpdate = state.updatedForces[forceKey];
137	  return {
138	    ...state,
139	    updatedForces: {
140	      ...state.updatedForces,
141	      [forceKey]: { ...existingUpdate, [field]: value },
142	    },
143	  };
144	}
145	
146	/** Appends a new component column. Throws if `component.name` already exists in baseComponents or addedComponents. */
147	export function addComponentColumn(state: PendingState, component: SnapshotComponent): PendingState {
148	  const exists =
149	    state.baseComponents.some((c) => c.name === component.name) ||
150	    state.addedComponents.some((c) => c.name === component.name);
151	  if (exists) {
152	    throw new Error(`component "${component.name}" already exists`);
153	  }
154	  return { ...state, addedComponents: [...state.addedComponents, component] };
155	}
156	
157	/** Appends a new attractor option. Throws if `attractor.id` already exists in baseAttractors or addedAttractors. */
158	export function addAttractorOption(state: PendingState, attractor: SnapshotAttractor): PendingState {
159	  const exists =
160	    state.baseAttractors.some((a) => a.id === attractor.id) ||
161	    state.addedAttractors.some((a) => a.id === attractor.id);
162	  if (exists) {
163	    throw new Error(`attractor "${attractor.id}" already exists`);
164	  }
165	  return { ...state, addedAttractors: [...state.addedAttractors, attractor] };
166	}
